  $url='https://app.divera247.com/api/v2/alarms?accesskey='.rawurlencode($key);
  $ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>15,CURLOPT_CONNECTTIMEOUT=>5,CURLOPT_HTTPHEADER=>['Accept: application/json'],CURLOPT_USERAGENT=>'FwDesk-Halchter/1.0']);
  $response=curl_exec($ch);$http=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);$error=curl_error($ch);curl_close($ch);
  if($response===false||$http<200||$http>=300){$msg=$error!==''?$error:'HTTP '.$http;header('Location:?divera=error&msg='.rawurlencode($msg));exit;}
  $payload=json_decode($response,true);
  if(!is_array($payload)||($payload['success']??false)!==true){header('Location:?divera=error&msg='.rawurlencode('Ungültige Divera-Antwort'));exit;}
  $items=$payload['data']['items']??[];$imported=0;$skipped=0;$check=$db->prepare('SELECT id FROM incidents WHERE divera_id=? OR incident_number=? LIMIT 1');$ins=$db->prepare('INSERT INTO incidents(incident_number,title,location,incident_date,alarm_time,divera_id) VALUES(?,?,?,?,?,?)');
  foreach($items as $item){$foreign=trim((string)($item['foreign_id']??''));$title=trim((string)($item['title']??''));$address=trim((string)($item['address']??''));if($foreign===''||$title==='')continue;$check->execute([$foreign,$foreign]);if($check->fetchColumn()){$skipped++;continue;}$ts=(int)($item['date']??time());$ins->execute([$foreign,$title,$address,date('Y-m-d',$ts),date('H:i',$ts),$foreign]);$imported++;}
  header('Location:?divera=imported&count='.$imported.'&skipped='.$skipped);exit;
 }
 if($form==='divera_users_import'){
