  $response=curl_exec($ch);$http=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);$error=curl_error($ch);curl_close($ch);
  if($response===false||$http<200||$http>=300){$msg=$error!==''?$error:'HTTP '.$http;header('Location:?action=master&divera=users_error&msg='.rawurlencode($msg));exit;}
  $payload=json_decode($response,true);if(!is_array($payload)||(($payload['success']??true)!==true)){header('Location:?action=master&divera=users_error&msg='.rawurlencode('Ungültige Divera-Benutzerantwort'));exit;}
  $items=$payload['data']['items']??($payload['items']??($payload['data']??[]));if(!is_array($items)){header('Location:?action=master&divera=users_error&msg='.rawurlencode('Keine Benutzerliste in der Divera-Antwort gefunden'));exit;}
  $imported=0;$updated=0;$skipped=0;$find=$db->prepare('SELECT id FROM personnel WHERE user_id=? LIMIT 1');$ins=$db->prepare('INSERT INTO personnel(name,user_id) VALUES(?,?)');$upd=$db->prepare('UPDATE personnel SET name=?,user_id=?,active=1 WHERE id=?');
  foreach($items as $item){if(!is_array($item))continue;$userId=trim((string)($item['user_id']??$item['id']??''));$first=trim((string)($item['firstname']??$item['first_name']??''));$last=trim((string)($item['lastname']??$item['last_name']??''));$name=trim(preg_replace('/\s+/',' ',trim($first.' '.$last)));if($userId===''||$name===''){$skipped++;continue;}$find->execute([$userId]);$existingPerson=$find->fetchColumn();if($existingPerson){$upd->execute([$name,$userId,(int)$existingPerson]);$updated++;}else{$ins->execute([$name,$userId]);$imported++;}}
