function headerHtml(string $title='FW Verwaltung'):void{echo '<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.h($title).'</title><style>body{font-family:system-ui;margin:0;background:#f3f5f7;color:#18212b}header{background:#17212b;color:#fff;padding:16px 24px}.topbar{display:flex;align-items:center;justify-content:space-between;gap:24px;white-space:nowrap}.brand{flex:0 0 auto;white-space:nowrap}.topnav{display:flex;gap:18px;align-items:center;overflow-x:auto;white-space:nowrap}.topnav a{color:#fff;text-decoration:none;white-space:nowrap;display:inline-block}main{max-width:1200px;margin:24px auto;padding:0 16px}.card{background:#fff;border-radius:14px;padding:20px;margin-bottom:18px;box-shadow:0 2px 10px #0001}label{display:block;font-weight:600;margin:10px 0 5px}input,textarea,select{width:100%;box-sizing:border-box;padding:10px;border:1px solid #ccd3da;border-radius:8px}button,.btn{background:#d62828;color:#fff;border:0;border-radius:8px;padding:10px 16px;cursor:pointer;text-decoration:none;display:inline-block}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:16px}.time-grid{display:grid;grid-template-columns:120px 150px minmax(180px,1fr) 150px;gap:16px;align-items:end}.time-grid input{min-width:0}.duration-box{font-weight:600}.duration-value{background:#f3f5f7;min-height:20px;padding:10px;border:1px solid #ccd3da;border-radius:8px;white-space:nowrap}.muted{color:#667}.crew,.material-list,.person-block,.master-row{border:1px solid #ddd;border-radius:10px;padding:12px;margin:10px 0}.check{display:inline-block;margin:5px 12px 5px 0}.check input{width:auto}.person-choice.disabled{opacity:.35}.person-na .person-detail{background:#eee;color:#888;opacity:.65}.person-na .person-detail::placeholder{color:#999}.danger{background:#eee;color:#222}.actions{display:flex;gap:10px;flex-wrap:wrap}.material-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:4px 16px}.material-list label{margin:5px 0;font-weight:500}.master-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(330px,1fr));gap:18px}.person-grid{align-items:start}@media(max-width:900px){.topbar{align-items:flex-start}.topnav{gap:12px}}@media(max-width:800px){.time-grid{grid-template-columns:1fr 1fr}.duration-box{grid-column:1/-1}.topbar{display:block}.topnav{margin-top:12px}.person-grid{grid-template-columns:1fr}}@media print{body{background:#fff}.topnav,header{display:none!important}main{max-width:none;margin:0;padding:0}.card{box-shadow:none;border:0}.actions{display:none!important}.person-grid{grid-template-columns:repeat(3,1fr)}}</style></head><body><header><div class="topbar"><div class="brand"><strong>🚒 FwDesk Halchter</strong><div style="font-size:13px;opacity:.8;margin-top:3px">Die digitale Einsatzdoku für Feuerwehren</div></div><nav class="topnav"><a href="?">Einsätze</a><a href="?action=new">+ Neuer Einsatz</a><a href="?action=master">Stammdaten</a></nav></div></header><main>';}
function footerHtml():void{echo '</main></body></html>';}
function selectedType(string $current,string $value):string{return $current===$value?' selected':'';}
function personDataDisabled(string $type):string{return $type==='n/a'?' person-na':'';}
function incidentForm(PDO $db,array $vehicles,array $people,?array $incident=null):void{
 $isEdit=$incident!==null;$assignedVehicles=[];$assignedCrew=[];if($isEdit){$q=$db->prepare('SELECT vehicle_id FROM incident_vehicles WHERE incident_id=?');$q->execute([(int)$incident['id']]);$assignedVehicles=array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN));$q=$db->prepare('SELECT vehicle_id,personnel_id FROM incident_personnel WHERE incident_id=?');$q->execute([(int)$incident['id']]);foreach($q->fetchAll(PDO::FETCH_ASSOC) as $row)$assignedCrew[(int)$row['vehicle_id']][]=(int)$row['personnel_id'];}
 $val=fn(string $key,string $default='')=>h($incident[$key]??$default);echo '<div class="card"><h1>'.($isEdit?'Einsatz bearbeiten':'Neuer Einsatz').'</h1><form method="post"><input type="hidden" name="form" value="incident">'.($isEdit?'<input type="hidden" name="incident_id" value="'.(int)$incident['id'].'">':'');echo '<label>Einsatznummer</label><input name="incident_number" value="'.$val('incident_number').'" placeholder="z. B. 2026-123"><label>Einsatz / Stichwort</label><input name="title" required value="'.$val('title').'" placeholder="z. B. Ölspur"><label>Einsatzort</label><input name="location" required value="'.$val('location').'" placeholder="z. B. Halchterstr. 2"><div class="time-grid"><div><label>Datum</label><input type="date" name="incident_date" value="'.$val('incident_date',date('Y-m-d')).'" required></div><div><label>Alarmierung</label><input type="time" name="alarm_time" value="'.$val('alarm_time').'" title="Zeitpunkt der Alarmierung"></div><div><label>Beginn <span class="muted">(Ende der kostenlosen gesetzlichen Hilfe)</span></label><input type="time" id="start_time" name="start_time" value="'.$val('start_time').'" title="Beginn des Einsatzes" oninput="updateDuration()"></div><div><label>Ende</label><input type="time" id="end_time" name="end_time" value="'.$val('end_time').'" title="Ende des Einsatzes" oninput="updateDuration()"></div><div class="duration-box"><label>Dauer</label><div id="duration_value" class="duration-value">–</div></div></div><div class="grid"><div><label>Einsatzleiter</label><input name="incident_leader" value="'.$val('incident_leader').'"></div><div><label>Dokument ausgefüllt von</label><input name="document_filled_by" value="'.$val('document_filled_by').'"></div></div><h2>Fahrzeuge und Besatzung</h2>';foreach($vehicles as $v){$vid=(int)$v['id'];$checked=in_array($vid,$assignedVehicles,true);echo '<div class="crew"><label class="check"><input type="checkbox" name="vehicles[]" value="'.$vid.'" '.($checked?'checked':'').' onchange="toggleVehicle(this)"> 🚒 '.h($v['name']).' <span class="muted">'.h($v['call_sign']).'</span></label><div class="crewlist" '.($checked?'':'hidden').'>';if(!$people)echo '<span class="muted">Noch kein Personal angelegt.</span>';foreach($people as $p){$pid=(int)$p['id'];$pc=in_array($pid,$assignedCrew[$vid]??[],true);echo '<label class="check person-choice" data-person-id="'.$pid.'"><input type="checkbox" class="crew-person" name="crew['.$vid.'][]" value="'.$pid.'" '.($pc?'checked':'').' onchange="syncPersonSelection('.$pid.',this)"> '.h($p['name']).'</label>';}echo '</div></div>';}$val('material');echo '<label>Sonstiges Material (Freitext)</label><textarea name="material" rows="3">'.$val('material').'</textarea><label>Bemerkungen</label><textarea name="notes" rows="4">'.$val('notes').'</textarea><h2>Persondaten</h2><div class="grid person-grid">';foreach([['1','culprit1','Verursacher'],['2','culprit2','n/a'],['3','culprit_unknown','n/a']] as $p){$key=$p[1];$default=$p[2];$type=$incident[$key.'_type']??$default;echo '<div class="person-block"><h3>Person '.$p[0].'</h3><label>Zuordnung</label><select name="'.$key.'_type"><option value="Verursacher"'.selectedType($type,'Verursacher').'>Verursacher</option><option value="Verursacher 2"'.selectedType($type,'Verursacher 2').'>Verursacher 2</option><option value="Unbekannt"'.selectedType($type,'Unbekannt').'>Unbekannt</option><option value="n/a"'.selectedType($type,'n/a').'>n/a</option></select><label>Name</label><input class="person-detail" name="'.$key.'_name" value="'.$val($key.'_name').'"><label>Geburtsdatum</label><input class="person-detail" type="date" name="'.$key.'_birthdate" value="'.$val($key.'_birthdate').'"><label>Adresse</label><textarea class="person-detail" name="'.$key.'_address" rows="2">'.$val($key.'_address').'</textarea></div>'; }echo '</div><div class="actions"><button type="submit">'.($isEdit?'Änderungen speichern':'Einsatz speichern').'</button></div></form></div>';echo '<script>function updateDuration(){var s=document.getElementById("start_time"),e=document.getElementById("end_time"),d=document.getElementById("duration_value");if(!s||!e||!d)return;if(!s.value||!e.value){d.textContent="–";return;}var sp=s.value.split(":").map(Number),ep=e.value.split(":").map(Number),start=sp[0]*60+sp[1],end=ep[0]*60+ep[1];if(end<start)end+=1440;var minutes=end-start;d.textContent=Math.floor(minutes/60)+" Std. "+(minutes%60)+" Min.";}function syncPersonSelection(id,changed){document.querySelectorAll(".crew-person").forEach(function(cb){if(cb.value!==String(id))return;var label=cb.closest(".person-choice");if(changed===cb)return;cb.disabled=changed.checked;label.classList.toggle("disabled",changed.checked);});}function toggleVehicle(v){var crew=v.closest(".crew").querySelector(".crewlist");crew.hidden=!v.checked;}document.addEventListener("DOMContentLoaded",function(){updateDuration();});</script>';
}
headerHtml();
if($action==='new'){incidentForm($db,$vehicles,$people);}
elseif($action==='edit'){$s=$db->prepare('SELECT * FROM incidents WHERE id=?');$s->execute([$editId]);$incident=$s->fetch(PDO::FETCH_ASSOC);if(!$incident)echo '<div class="card"><h1>Einsatz nicht gefunden</h1></div>';else incidentForm($db,$vehicles,$people,$incident);}
elseif($action==='master'){
 $personStatus=$_GET['person']??'';$vehicleStatus=$_GET['vehicle']??'';
 echo '<div class="card"><h1>Stammdaten</h1><p class="muted">Personal und Fahrzeuge können hier direkt bearbeitet werden. Eine feste Zuordnung von Personal zu einem Fahrzeug gibt es nicht.</p><h2>🔗 Divera 24/7</h2><form method="post"><input type="hidden" name="form" value="divera_settings"><label>AccessKey</label><input type="password" name="divera_access_key" value="'.h($diveraAccessKey).'"><br><button>AccessKey speichern</button></form></div><div class="master-grid">';
 echo '<div class="card"><h2>👨‍🚒 Personal</h2><form method="post"><input type="hidden" name="form" value="person"><label>Name</label><input name="name" required><br><button>Person anlegen</button></form><hr>';if($personStatus==='deleted')echo '<p class="muted">Person gelöscht.</p>';elseif($personStatus==='in_use')echo '<p class="muted">Person kann nicht gelöscht werden, da sie bereits einem Einsatz zugeordnet ist.</p>';foreach($people as $p)echo '<div class="master-row"><form method="post"><input type="hidden" name="form" value="person"><input type="hidden" name="id" value="'.$p['id'].'"><label>Name</label><input name="name" value="'.h($p['name']).'" required><div class="muted">Divera User-ID: '.h($p['user_id']??'').'</div><br><div class="actions"><button type="submit">Speichern</button><button type="submit" class="danger" name="form" value="delete_person" onclick="return confirm(\'Person wirklich löschen?\')">🗑️ Löschen</button></div></form></div>';echo '<div class="actions"><form method="post"><input type="hidden" name="form" value="divera_users_import"><button type="submit">📥 Divera User importieren</button></form></div></div>';
 echo '<div class="card"><h2>🚒 Fahrzeuge</h2><form method="post"><input type="hidden" name="form" value="vehicle"><div class="inline"><div><label>Bezeichnung</label><input name="name" required placeholder="LF 8"></div><div><label>Funkrufname</label><input name="call_sign" placeholder="LF 8"></div></div><br><button>Fahrzeug anlegen</button></form><hr>';if($vehicleStatus==='deleted')echo '<p class="muted">Fahrzeug gelöscht.</p>';elseif($vehicleStatus==='in_use')echo '<p class="muted">Fahrzeug kann nicht gelöscht werden, da es bereits einem Einsatz zugeordnet ist.</p>';foreach($vehicles as $v)echo '<div class="master-row"><form method="post"><input type="hidden" name="form" value="vehicle"><input type="hidden" name="id" value="'.$v['id'].'"><div class="inline"><div><label>Bezeichnung</label><input name="name" value="'.h($v['name']).'" required></div><div><label>Funkrufname</label><input name="call_sign" value="'.h($v['call_sign']).'"></div></div><br><div class="actions"><button type="submit">Speichern</button><button type="submit" class="danger" name="form" value="delete_vehicle" onclick="return confirm(\'Fahrzeug wirklich löschen?\')">🗑️ Löschen</button></div></form></div>';echo '</div>';
}
elseif($action==='view'){ $s=$db->prepare('SELECT * FROM incidents WHERE id=?');$s->execute([$editId]);$i=$s->fetch(PDO::FETCH_ASSOC);if(!$i)echo '<div class="card"><h1>Einsatz nicht gefunden</h1></div>';else echo '<div class="card"><div class="actions"><a class="btn" href="?action=edit&id='.(int)$i['id'].'">✏️ Bearbeiten</a><button onclick="window.print()">🖨️ PDF / Drucken</button></div><h1>'.h($i['title']).'</h1><p><strong>Einsatznummer:</strong> '.h($i['incident_number']).'</p><p><strong>Einsatzort:</strong> '.h($i['location']).'</p><p><strong>Datum:</strong> '.h($i['incident_date']).'</p><p><strong>Beginn:</strong> '.h($i['start_time']).' &nbsp; <strong>Ende:</strong> '.h($i['end_time']).'</p></div>';}
else{echo '<div class="card"><h1>Einsätze</h1><div class="actions"><a class="btn" href="?action=new">+ Neuer Einsatz</a><form method="post" style="display:inline"><input type="hidden" name="form" value="divera_import"><button type="submit">📥 Divera Import</button></form></div>'; $rows=$db->query('SELECT * FROM incidents ORDER BY incident_date DESC,id DESC')->fetchAll(PDO::FETCH_ASSOC);foreach($rows as $r)echo '<div class="master-row"><a href="?action=view&id='.(int)$r['id'].'"><strong>'.h($r['incident_number']).' – '.h($r['title']).'</strong></a><div class="muted">'.h($r['incident_date']).' · '.h($r['location']).'</div></div>';echo '</div>';}
